inline uint32_t hash(uint32_t d, const uint8_t* str, int len) {
  if (d == 0) d = 0x01000193;
  for (int i = 0; i < len; i++)
    d = ((d * 0x01000193) ^ (uint32_t)str[i]) & 0xffffffff;
  return d;
}

inline int16_t lookup(const uint8_t* str, int len) {
  int d = G[hash(0, str, len) % G_size];
  d = V[d < 0 ? (-d - 1) : (hash(d, str, len) % V_size)];
  return (strncmp((const char*)str, (const char*)exactMap + exactIndex[d], len) == 0) ? d : -1;
}

